<?php
require dirname(__DIR__).'/includes/bootstrap.php';require ROOT_PATH.'/includes/services.php';require_staff_or_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');$id=int_post('id');$u=current_user();try{if($action==='update_reason'){if(post('reason')==='')throw new RuntimeException('กรุณากรอกวัตถุประสงค์');execute_sql("UPDATE tbl_devices_service SET ser_reason=? WHERE ser_id=? AND ser_status IN ('approved','borrowed')",[post('reason'),$id]);flash('success','แก้ไขวัตถุประสงค์เรียบร้อย');}elseif($action==='return'){return_loan_tx($id,int_post('return_status'),(int)$u['m_id'],full_name($u));flash('success','บันทึกรับคืนครุภัณฑ์เรียบร้อย');}}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('staff/loans.php');}
$rows=fetch_all("SELECT s.*,m.m_fname,m.m_name,m.m_lname,m.m_email,d.d_name,d.d_id,d.d_img,t.t_name FROM tbl_devices_service s JOIN tbl_member m ON m.m_id=s.ref_m_id JOIN tbl_devices d ON d.d_id=s.ref_d_id LEFT JOIN tbl_devices_type t ON t.t_id=s.ref_t_id WHERE s.ser_status IN ('approved','borrowed') ORDER BY s.ser_date_lend DESC,s.ser_id DESC");render_header('รายการกำลังยืม','loans');
?>
<div class="page-intro"><div><h2>ครุภัณฑ์ที่กำลังถูกยืม</h2><p>รับคืนครุภัณฑ์และระบุสภาพหลังคืนเป็น “พร้อมใช้งาน” หรือ “ชำรุด”</p></div><a class="btn btn-primary" href="<?=e(url('staff/direct_loan.php'))?>">+ บันทึกยืม</a></div><div class="card"><div class="table-tools"><div class="table-search"><input type="search" placeholder="ค้นหาผู้ยืม หรือครุภัณฑ์…" data-table-search="#loanTable"></div><span class="table-meta"><?=count($rows)?> รายการ</span></div><div class="table-wrap"><table class="data-table" id="loanTable"><thead><tr><th>ครุภัณฑ์</th><th>ผู้ยืม</th><th>วัตถุประสงค์</th><th>วันที่ยืม</th><th>เจ้าหน้าที่</th><th>รับคืน</th></tr></thead><tbody><?php if(!$rows):?><tr data-empty><td colspan="6"><div class="empty-state"><div class="empty-icon">✓</div><h3>ไม่มีครุภัณฑ์ค้างยืม</h3></div></td></tr><?php else:foreach($rows as $r):$img=device_image($r);?><tr><td><div class="device-cell"><?php if($img):?><img class="device-thumb" src="<?=e($img)?>" alt=""><?php else:?><span class="device-placeholder">ET</span><?php endif;?><span><b class="cell-title"><?=e($r['d_name'])?></b><small class="cell-sub"><?=e($r['d_id'])?> • <?=e($r['t_name']?:'-')?></small></span></div></td><td><b class="cell-title"><?=e(full_name($r))?></b><small class="cell-sub"><?=e($r['m_email']?:'-')?></small></td><td><form method="post" class="btn-group" style="min-width:240px"><?=csrf_field()?><input type="hidden" name="action" value="update_reason"><input type="hidden" name="id" value="<?=e($r['ser_id'])?>"><input class="form-control" style="height:34px" name="reason" maxlength="255" value="<?=e($r['ser_reason'])?>"><button class="btn btn-soft btn-sm">บันทึก</button></form></td><td><?=e(thai_date($r['ser_date_lend']))?></td><td><?=e($r['ser_staff_name_lend']?:'-')?></td><td><div class="btn-group"><form method="post" data-confirm="ยืนยันรับคืนและเปลี่ยนสถานะเป็นพร้อมใช้งาน?" data-confirm-title="รับคืนครุภัณฑ์"><?=csrf_field()?><input type="hidden" name="action" value="return"><input type="hidden" name="id" value="<?=e($r['ser_id'])?>"><input type="hidden" name="return_status" value="1"><button class="btn btn-success btn-sm">คืนปกติ</button></form><form method="post" data-confirm="รับคืนและบันทึกครุภัณฑ์เป็นชำรุด?" data-confirm-title="รับคืนเป็นชำรุด"><?=csrf_field()?><input type="hidden" name="action" value="return"><input type="hidden" name="id" value="<?=e($r['ser_id'])?>"><input type="hidden" name="return_status" value="3"><button class="btn btn-danger-soft btn-sm">คืนชำรุด</button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php render_footer();?>
